  const reqs=['anna','peter'].map(w=>({w,m:S.mem[w],ims:w==='anna'?S.p.ims:S.c.ims}));
  const comp=S.p.price<=S.c.max+1e-9;
  const ok=Math.abs(a.debT-a.credT)<1e-9&&Math.abs(a.debT-a.netT-a.comT)<1e-9;
